const D = { energy: .62, scale: 1, aniso: .6, speed: 1, density: .5, feed: .046, kill: .0612, hue: 18, x: .5, y: .5, style: 'coral-horn', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>v<a?a:v>b?b:v, W=width, H=height;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;
const hsh=i=>{const s=Math.sin(i*127.1+(P.seed|0)*311.7)*43758.5453;return s-Math.floor(s);};

// --- coarse grid, size+seed keyed (<=160 wide) ---
const LS=150;
const GW=clp(Math.round(LS*W/Math.max(W,H)),48,160)|0;
const GH=clp(Math.round(LS*H/Math.max(W,H)),28,160)|0;
const N=GW*GH, key=GW+'x'+GH+'_'+(P.seed|0);
if(!S.A||S.key!==key){
  S.key=key;
  S.A=new Float32Array(N); S.B=new Float32Array(N);
  S.A2=new Float32Array(N); S.B2=new Float32Array(N);
  S.aoff=hsh(7)*6.283;
  for(let i=0;i<N;i++){ const r=hsh(i*2+1), r2=hsh(i*2+2); S.A[i]=1-0.35*r; S.B[i]=r2<0.16?0.55*hsh(i*3+5):0.02*r2; }
  if(S.buf&&S.buf.remove)S.buf.remove();
  S.buf=createGraphics(GW,GH); S.buf.pixelDensity(1);
  S.burn=140; // develop labyrinth before first visible frame (no uniform/static open)
}
let a=S.A,b=S.B,a2=S.A2,b2=S.B2; const buf=S.buf;

// --- regime dramaturgy: feed/kill wander through fingerprint/maze/horn on section, wobble on K.t ---
const pf=[[0.037,0.060],[0.030,0.0575],[0.046,0.0612],[0.054,0.062],[0.058,0.0625],[0.042,0.059],[0.034,0.058],[0.050,0.0615]];
const ps=pf[((K.section|0)%8+8)%8];
const feed=clp(P.feed*0.4 + ps[0]*0.6 + 0.004*Math.sin(K.t*0.03), 0.018, 0.085);
const kill=clp(P.kill*0.4 + ps[1]*0.6 + 0.0022*Math.sin(K.t*0.021+1.3), 0.05, 0.072);

// --- anisotropy tensor, angle drifts continuously on K.t => ridges perpetually reorganize (motion floor) ---
const th=K.t*0.02*(0.4+P.speed*0.7) + (K.section|0)*0.85 + S.aoff;
const kk=clp(P.aniso,0,1)*0.82;
const c2=Math.cos(2*th), s2=Math.sin(2*th);
const D0a=0.13, D0b=0.065;
const Ax=D0a*(1+kk*c2), Ay=D0a*(1-kk*c2), Axy=D0a*kk*s2;
const Bx=D0b*(1+kk*c2), By=D0b*(1-kk*c2), Bxy=D0b*kk*s2;

// --- perpetual micro-injection (safety against die-to-uniform; K baseline carries it, audio only adds) ---
const inj=0.10+K.pulse*0.10+A.bass*0.18;
const ix=Math.floor((0.5+(P.x-0.5)*0.6+0.34*Math.cos(K.t*0.07))*GW);
const iy=Math.floor((0.5+(P.y-0.5)*0.6+0.34*Math.sin(K.t*0.052))*GH);
const rr=1+Math.round(P.density*2);
for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
  if(dx*dx+dy*dy>rr*rr)continue;
  const x=((ix+dx)%GW+GW)%GW, y=((iy+dy)%GH+GH)%GH, i=y*GW+x;
  b[i]=Math.min(1,b[i]+inj*0.35);
}

// --- integrate Gray-Scott with anisotropic (tensor) diffusion; >=1 step every frame ---
const steps=clp(Math.round((2+P.speed*8)*(0.6+0.6*K.intensity)),1,16)+(S.burn>0?S.burn:0);
let sa=a,sb=b,da=a2,db=b2;
for(let it=0; it<steps; it++){
  for(let y=0;y<GH;y++){
    const ym=(y-1+GH)%GH, yp=(y+1)%GH, r0=ym*GW, r1=y*GW, r2=yp*GW;
    for(let x=0;x<GW;x++){
      const xm=(x-1+GW)%GW, xp=(x+1)%GW, i=r1+x;
      const aC=sa[i], bC=sb[i];
      const aE=sa[r1+xp],aW=sa[r1+xm],aN=sa[r0+x],aS=sa[r2+x];
      const aNE=sa[r0+xp],aNW=sa[r0+xm],aSE=sa[r2+xp],aSW=sa[r2+xm];
      const bE=sb[r1+xp],bW=sb[r1+xm],bN=sb[r0+x],bS=sb[r2+x];
      const bNE=sb[r0+xp],bNW=sb[r0+xm],bSE=sb[r2+xp],bSW=sb[r2+xm];
      const lapA=Ax*(aE+aW-2*aC)+Ay*(aN+aS-2*aC)+Axy*0.5*(aNE+aSW-aNW-aSE);
      const lapB=Bx*(bE+bW-2*bC)+By*(bN+bS-2*bC)+Bxy*0.5*(bNE+bSW-bNW-bSE);
      const rab=aC*bC*bC;
      let na=aC+lapA-rab+feed*(1-aC);
      let nb=bC+lapB+rab-(kill+feed)*bC;
      da[i]=na<0?0:na>1?1:na; db[i]=nb<0?0:nb>1?1:nb;
    }
  }
  const ta=sa;sa=da;da=ta; const tb=sb;sb=db;db=tb;
}
if(sa!==S.A){ S.A.set(sa); S.B.set(sb); }
S.burn=0;
const fA=S.A, fB=S.B;

// --- field -> RGB straight into buffer pixels (RAW RGBA — HSB does NOT apply here) ---
const st=P.style, e=P.energy, gain=0.55+e*1.2;
const hr=((P.hue%360)+360)%360/360*6.283;
const tR=0.55+0.45*Math.cos(hr), tG=0.55+0.45*Math.cos(hr-2.094), tB=0.55+0.45*Math.cos(hr+2.094);
function ramp(v,s){ const n=s.length-1, ff=clp(v,0,1)*n; let k=ff|0; if(k>n-1)k=n-1; const t=ff-k;
  return [s[k][0]+(s[k+1][0]-s[k][0])*t, s[k][1]+(s[k+1][1]-s[k][1])*t, s[k][2]+(s[k+1][2]-s[k][2])*t]; }
const CORAL=[[30,12,16],[92,38,32],[196,84,52],[238,206,176]];
const BRAIN=[[62,54,66],[120,104,116],[214,150,166],[244,214,222]];
const IRON=[[6,4,14],[74,10,86],[210,44,30],[248,150,20],[252,238,168]];
const BIO=[[4,14,20],[8,52,64],[26,150,150],[150,248,232]];
buf.loadPixels(); const px=buf.pixels;
for(let y=0;y<GH;y++){
  const ym=(y-1+GH)%GH, yp=(y+1)%GH, r0=ym*GW, r1=y*GW, r2=yp*GW;
  for(let x=0;x<GW;x++){
    const xm=(x-1+GW)%GW, xp=(x+1)%GW, i=r1+x;
    const bv=fB[i];
    const gx=fB[r1+xp]-fB[r1+xm], gy=fB[r2+x]-fB[r0+x];
    const gm=Math.sqrt(gx*gx+gy*gy);
    const v=clp(bv*2.05*gain-0.21,0,1);
    const rim=clp(gm*7.2*gain,0,1);
    let r,g,bl;
    if(st==='fingerprint'){ // abstract: dark ink ridges on cream paper, mono
      const ink=clp((v-0.30)*3.4,0,1)*0.92 + rim*0.25;
      const p=1-clp(ink,0,1);
      r=30+p*208; g=26+p*204; bl=24+p*188;
    } else if(st==='thermal'){
      const c=ramp(v,IRON); r=c[0]; g=c[1]; bl=c[2];
