      r=c[0]*(1-lift)+250*lift; g=c[1]*(1-lift)+232*lift; bl=c[2]*(1-lift)+208*lift;
    }
    // gentle hue tint (brightness-preserving-ish)
    r*=(0.72+0.56*tR); g*=(0.72+0.56*tG); bl*=(0.72+0.56*tB);
    const j=i*4; px[j]=clp(r,0,255); px[j+1]=clp(g,0,255); px[j+2]=clp(bl,0,255); px[j+3]=255;
  }
}
buf.updatePixels();

// --- composite: upscale full-frame; P.scale = display zoom on centered sub-rect ---
const zoom=clp(P.scale,1,2.6), sw=GW/zoom, sh=GH/zoom;
const sx=clp((GW-sw)*(0.15+P.x*0.7),0,GW-sw), sy=clp((GH-sh)*(0.15+P.y*0.7),0,GH-sh);
